shots.draw_js:
clearScene();setBig(null);setEq(null);
note("新策略比旧策略好多少",640,280,"y lg");
note("要能写成一个式子",640,350,"g lg");
setCap("要保证「每步都不变差」，先得能<b>精确地写出差了多少</b>。");

clearScene();setEq(null);
setBig("优势当然用新策略的","我们在评价新策略，那就用它的 A");
setCap("学生在课上问的正是这个 —— <b>答案是：不，用旧策略的</b>。");

clearScene();setBig(null);
setEq("$$V(\\tilde\\pi)=V(\\pi)+\\mathbb{E}_{s,a\\sim\\tilde\\pi}\\Big[\\textstyle\\sum_t\\gamma^t A^{\\pi}(s_t,a_t)\\Big]$$","top");
note("分布用新策略",400,320,"v lg");
note("优势用旧策略",880,320,"b lg");
setCap("<b>相对性能恒等式</b>：分布来自<b>新</b>策略，优势来自<b>旧</b>策略。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"A^π 可算",sub:"旧策略的数据在手",state:"on"},
  {label:"分布 ~ π̃",sub:"还没有它的数据",state:"dead"},
  {label:"所以",sub:"恒等式不可直接估",state:"dead"}]});
note("这正是下两集要解决的",640,420,"y");
setCap("恒等式是<b>精确</b>的 —— 但右边那个期望<b>算不出来</b>。");

clearScene();setBig(null);setEq(null);
note("优势：旧",400,290,"b lg");
note("分布：新",880,290,"v lg");
note("反了推导就倒过来",640,400,"r lg");
setCap("<b>指名反驳</b>：优势用<b>旧</b>策略的。<b>这不是可以两边都行的记号选择。</b>");

clearScene();setBig(null);
setEq("$$\\textstyle\\sum_t \\gamma^t P(s_t=s\\mid\\pi)$$","top");
note("上一集那个分布",640,300,"y lg");
note("它到底是什么",640,360,"r lg");
setCap("上一集那个期望是对<b>这个东西</b>取的。先把它的身份弄清楚。");

clearScene();setEq(null);
setBig("它就是平稳分布","带个折扣而已");
setCap("讲座原话是「带折扣的平稳分布」 —— <b>而它根本不是一个分布</b>。");

clearScene();setBig(null);
setEq("$$\\textstyle\\sum_s\\sum_t\\gamma^t P(s_t=s)=\\textstyle\\sum_t\\gamma^t=\\frac{1}{1-\\gamma}$$","top");
note("和是 1/(1−γ)，不是 1",640,320,"r lg");
setCap("把它全部加起来：每个 t 的概率和是 1，于是总和是 <b>Σγᵗ = 1/(1−γ)</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:760,vals:[10,100],
  x:380,y:430,w:520,h:170,max:110,
  label:function(i){return ["γ=0.9","γ=0.99"][i];},
  cls:function(i){return i===1?"r":"v";},
  fmt:function(v){return String(v);}});
note("它的总和（分布应为 1）",640,466,"r");
setCap("γ=0.9 时和是 <b>10</b>，γ=0.99 时是 <b>100</b> —— 而分布的和该是 1。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"平稳分布",sub:"和为 1 · 要不可约非周期",state:"on"},
  {label:"折扣占用测度",sub:"和为 1/(1−γ) · 未归一化",state:"on"},
  {label:"讲座",sub:"两者混用",state:"dead"}]});
note("差一个 1/(1−γ)",640,420,"r");
setCap("<b>指名反驳</b>：它是<b>折扣占用测度</b>，不是平稳分布。两者差 1/(1−γ)。");

clearScene();setBig(null);setEq(null);
note("恒等式精确",400,280,"g lg");
note("但分布来自 π̃",880,280,"r lg");
note("还没有它的数据",640,400,"r lg");
setCap("困境很具体：<b>要评估才能决定换不换，要换了才能评估</b>。");

clearScene();setEq(null);
setBig("那就先换过去采一批","试试看不就知道了");
setCap("可以试 —— 但第四集说过，<b>试错的代价是不可逆的</b>。");

clearScene();setBig(null);
setEq("$$L_{\\pi}(\\tilde\\pi)=V(\\pi)+\\mathbb{E}_{s\\sim\\pi,\\,a\\sim\\tilde\\pi}\\Big[\\textstyle\\sum_t\\gamma^t A^{\\pi}(s_t,a_t)\\Big]$$","top");
note("状态分布换成旧的",640,320,"g lg");
setCap("<b>代理目标 L_π</b>：只改一处 —— <b>状态分布用旧策略的</b>，于是可算了。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:760,vals:[49.5,198],
  x:380,y:430,w:520,h:170,max:220,
  label:function(i){return ["α=0.05","α=0.10"][i];},
  cls:function(i){return i===1?"r":"v";},
  fmt:function(v){return v.toFixed(1)+"ε";}});
note("γ=0.99 时的惩罚系数",640,466,"r");
setCap("CPI 下界的惩罚 <b>2εγα²/(1−γ)²</b>：α 翻倍，惩罚翻<b>四</b>倍。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"L_π 可算",sub:"用旧数据估",state:"on"},
  {label:"L_π(π)=V(π)",sub:"当前点精确",state:"on"},
  {label:"最后一步",sub:"讲座推到期中之后",state:"dead"}]});
note("下界铺好了，论证没走完",640,420,"y");
setCap("<b>指名反驳</b>：不必先换过去试。<b>但讲座在这里停了。</b>");
